// Manager Agent — internal performance report to management.
//
// Unlike the customer-facing agents, this one never messages a customer. It
// aggregates real CRM data into the digest management asked for, e.g.:
//   "You received 182 leads this week. 47 haven't been contacted.
//    18 are high intent. 7 are likely to close."
//
// The numbers are computed deterministically from live tables (chat_history,
// contacts, deals/pipeline_stages) — NOT generated by an LLM — so the report is
// exact, free, needs no API key, and can never hallucinate a figure. That is the
// right trade-off for a metric a manager will act on.
//
// Definitions (all optionally scoped to a single WhatsApp number):
//   * leads          — distinct contacts whose FIRST inbound message landed in
//                      the window (genuinely new leads, not repeat chatter).
//   * notContacted   — of those, the ones we have never sent an outbound message.
//   * highIntent     — new leads whose "Lead Score" custom field ≥ threshold.
//   * likelyToClose  — open deals sitting in a stage with probability ≥ 50%
//                      (Proposal Sent or later) — a real pipeline signal.
//   * wonThisWeek    — deals marked won in the window (+ their value).

const pool = require('../db');
const { resolveFieldId, normalizePhone } = require('../engine/contactMutations');

const DAY = "INTERVAL '1 day'";

async function computeMetrics({ waNumber = null, days = 7, highIntentThreshold = 30 } = {}) {
  const wa = waNumber ? normalizePhone(waNumber) : null;
  const d = Math.max(1, Math.min(365, parseInt(days, 10) || 7));

  // New leads this window + how many were never replied to.
  const { rows: leadRows } = await pool.query(
    `WITH first_seen AS (
       SELECT wa_number, contact_number, MIN(timestamp) AS first_ts
         FROM coexistence.chat_history
        WHERE direction = 'incoming' AND ($1::text IS NULL OR wa_number = $1)
        GROUP BY wa_number, contact_number
     ),
     new_leads AS (
       SELECT * FROM first_seen WHERE first_ts >= NOW() - ($2::int * ${DAY})
     )
     SELECT
       (SELECT COUNT(*) FROM new_leads) AS new_leads,
       (SELECT COUNT(*) FROM new_leads nl
          WHERE NOT EXISTS (
            SELECT 1 FROM coexistence.chat_history o
             WHERE o.wa_number = nl.wa_number
               AND o.contact_number = nl.contact_number
               AND o.direction = 'outgoing')) AS not_contacted`,
    [wa, d],
  );
  const newLeads = Number(leadRows[0]?.new_leads || 0);
  const notContacted = Number(leadRows[0]?.not_contacted || 0);

  // High-intent new leads by Lead Score. Guard the JSON value with a numeric
  // regex so a non-numeric field value can never blow up the ::numeric cast.
  let highIntent = 0;
  const scoreField = await resolveFieldId('Lead Score');
  if (scoreField) {
    const { rows } = await pool.query(
      `WITH first_seen AS (
         SELECT wa_number, contact_number, MIN(timestamp) AS first_ts
           FROM coexistence.chat_history
          WHERE direction = 'incoming' AND ($1::text IS NULL OR wa_number = $1)
          GROUP BY wa_number, contact_number
       ),
       new_leads AS (
         SELECT * FROM first_seen WHERE first_ts >= NOW() - ($2::int * ${DAY})
       )
       SELECT COUNT(*) AS c
         FROM new_leads nl
         JOIN coexistence.contacts c2
           ON c2.wa_number = nl.wa_number AND c2.contact_number = nl.contact_number
        WHERE (c2.custom_fields ->> $3) ~ '^-?[0-9]+(\\.[0-9]+)?$'
          AND (c2.custom_fields ->> $3)::numeric >= $4`,
      [wa, d, String(scoreField.id), highIntentThreshold],
    );
    highIntent = Number(rows[0]?.c || 0);
  }

  // Likely to close — open deals in a high-probability stage.
  const { rows: dealRows } = await pool.query(
    `SELECT COUNT(*) AS c
       FROM coexistence.deals dd
       JOIN coexistence.pipeline_stages s ON s.id = dd.stage_id
      WHERE dd.status = 'open' AND s.stage_type = 'open' AND s.probability >= 50
        AND ($1::text IS NULL OR dd.contact_wa_number = $1)`,
    [wa],
  );
  const likelyToClose = Number(dealRows[0]?.c || 0);

  // Won this window (count + value).
  const { rows: wonRows } = await pool.query(
    `SELECT COUNT(*) AS c, COALESCE(SUM(value), 0) AS val
       FROM coexistence.deals
      WHERE status = 'won' AND won_at >= NOW() - ($2::int * ${DAY})
        AND ($1::text IS NULL OR contact_wa_number = $1)`,
    [wa, d],
  );
  const wonThisWeek = Number(wonRows[0]?.c || 0);
  const wonValue = Number(wonRows[0]?.val || 0);

  // Message volume for context / responsiveness.
  const { rows: msgRows } = await pool.query(
    `SELECT
       COUNT(*) FILTER (WHERE direction = 'incoming') AS msgs_in,
       COUNT(*) FILTER (WHERE direction = 'outgoing') AS msgs_out
       FROM coexistence.chat_history
      WHERE timestamp >= NOW() - ($2::int * ${DAY})
        AND ($1::text IS NULL OR wa_number = $1)`,
    [wa, d],
  );
  const msgsIn = Number(msgRows[0]?.msgs_in || 0);
  const msgsOut = Number(msgRows[0]?.msgs_out || 0);

  const contactedRate = newLeads > 0 ? Math.round(((newLeads - notContacted) / newLeads) * 100) : null;

  return {
    windowDays: d,
    waNumber: wa,
    hasLeadScoreField: !!scoreField,
    leads: newLeads,
    notContacted,
    highIntent,
    likelyToClose,
    wonThisWeek,
    wonValue,
    msgsIn,
    msgsOut,
    contactedRate,
    generatedAt: new Date().toISOString(),
  };
}

// Deterministic plain-text digest in the manager's own phrasing.
function buildDigest(m) {
  const period = m.windowDays === 7 ? 'this week' : `in the last ${m.windowDays} days`;
  const lines = [];
  lines.push(`📊 Manager report — ${period}`);
  lines.push('');
  lines.push(`You received ${m.leads} lead${m.leads === 1 ? '' : 's'} ${period}.`);
  if (m.leads > 0) {
    lines.push(`${m.notContacted} haven't been contacted${m.contactedRate != null ? ` (${m.contactedRate}% replied)` : ''}.`);
    if (m.hasLeadScoreField) {
      lines.push(`${m.highIntent} are high intent.`);
    }
  }
  lines.push(`${m.likelyToClose} are likely to close (in a proposal-or-later stage).`);
  if (m.wonThisWeek > 0) {
    lines.push(`${m.wonThisWeek} deal${m.wonThisWeek === 1 ? '' : 's'} won${m.wonValue > 0 ? ` — ₹${m.wonValue.toLocaleString('en-IN')}` : ''}.`);
  }
  lines.push('');
  lines.push(`Messages: ${m.msgsIn} in, ${m.msgsOut} out.`);
  if (m.leads > 0 && m.notContacted > 0) {
    lines.push('');
    lines.push(`👉 Action: ${m.notContacted} new lead${m.notContacted === 1 ? '' : 's'} still waiting for a first reply.`);
  }
  if (!m.hasLeadScoreField) {
    lines.push('');
    lines.push('Tip: add a numeric "Lead Score" custom field so high-intent leads are highlighted here.');
  }
  return lines.join('\n');
}

async function generateReport(opts = {}) {
  const metrics = await computeMetrics(opts);
  return { metrics, digest: buildDigest(metrics) };
}

/* ----------------------- Weekly scheduled delivery ------------------------- */

// IST clock helpers (UTC+5:30).
function istNow() { return new Date(Date.now() + 5.5 * 3600 * 1000); }
function istIsoDay(d = istNow()) { const wd = d.getUTCDay(); return wd === 0 ? 7 : wd; } // 1=Mon..7=Sun
function istHourNow(d = istNow()) { return d.getUTCHours(); }
function istDateKey(d = istNow()) { return d.toISOString().slice(0, 10); } // YYYY-MM-DD

// Pure predicate (testable): is the weekly report due right now?
function isWeeklyDue(config, { istDay, istHour }) {
  if (!config || !config.enabled) return false;
  return istDay === config.day_of_week && istHour >= config.hour;
}

// Called on a schedule. No-op unless enabled, on the configured IST day/hour, and
// not already generated today (UNIQUE period_date makes the claim atomic).
async function deliverWeeklyIfDue() {
  const { rows } = await pool.query('SELECT * FROM coexistence.manager_report_config WHERE id = 1');
  const config = rows[0];
  if (!isWeeklyDue(config, { istDay: istIsoDay(), istHour: istHourNow() })) return { skipped: true };

  const periodDate = istDateKey();
  // Atomically claim today's slot; if another tick already did, bail.
  const claim = await pool.query(
    `INSERT INTO coexistence.manager_report_runs (period_date) VALUES ($1)
     ON CONFLICT (period_date) DO NOTHING RETURNING id`,
    [periodDate],
  );
  if (claim.rows.length === 0) return { skipped: true, reason: 'already generated today' };
  const runId = claim.rows[0].id;

  const { metrics, digest } = await generateReport({ days: config.window_days || 7 });

  // Best-effort WhatsApp delivery to the configured staff numbers. Delivery may
  // fail if a recipient has no open session and no template applies — the report
  // is still stored and viewable in-app, so the schedule is never silently lost.
  let deliveredTo = 0;
  const recipients = Array.isArray(config.recipients) ? config.recipients : [];
  if (config.wa_account_id && recipients.length > 0) {
    const { resolveAccount, insertPendingRow } = require('./messageSender');
    const { enqueueSend } = require('../queue/sendQueue');
    const { account, error } = await resolveAccount({ accountId: config.wa_account_id });
    if (!error && account) {
      for (const raw of recipients) {
        const to = String(raw || '').replace(/\D/g, '');
        if (!to) continue;
        try {
          const localId = await insertPendingRow({ account, toNumber: to, messageType: 'text', messageBody: digest });
          await enqueueSend({ kind: 'text', accountId: account.id, to, localMessageId: localId, payload: { body: digest } });
          deliveredTo++;
        } catch (e) {
          console.error(`[manager-report] delivery to ${to} failed: ${e.message}`);
        }
      }
    } else {
      console.error(`[manager-report] no sending account: ${error || 'not found'}`);
    }
  }

  await pool.query(
    `UPDATE coexistence.manager_report_runs SET digest = $2, metrics = $3, delivered_to = $4 WHERE id = $1`,
    [runId, digest, JSON.stringify(metrics), deliveredTo],
  );
  console.log(`[manager-report] weekly report generated for ${periodDate}, delivered to ${deliveredTo} recipient(s)`);
  return { generated: true, periodDate, deliveredTo };
}

module.exports = {
  computeMetrics, buildDigest, generateReport,
  deliverWeeklyIfDue, isWeeklyDue,
};
